/**
 * Every outline big enough to see, as one path, for the faint world behind the
 * country. One element rather than 169 keeps the loading screen cheap to
 * build; the microstates are excluded because at this scale they are smaller
 * than the stroke that would draw them.
 */
export const WORLD_PATH: string = Object.values(OUTLINES)
  .filter(o => !o.small)
  .map(o => o.d)
  .join('')
